import Foundation

// Localized strings live in Resources/Localizable.xcstrings. The keys are the Android string
// resource names (generated by scripts/convert-android-strings.mjs), so both apps share wording
// and the Sepedi, Xitsonga and Tshivenda translations.
//
// Views render these through Text(String), which shows the text verbatim. That matters because
// some strings contain a literal "%" (e.g. "100% chance of delicious") that SwiftUI's
// LocalizedStringKey path would try to treat as a format specifier.

/// Looks up a plain localized string.
func L(_ key: String) -> String {
    NSLocalizedString(key, comment: "")
}

/// Looks up a localized format string and fills in its arguments.
func LF(_ key: String, _ args: CVarArg...) -> String {
    String(format: L(key), locale: Locale.current, arguments: args)
}

/// Looks up a key that was an Android <plurals> resource.
func LP(_ key: String, _ count: Int) -> String {
    String.localizedStringWithFormat(L(key), count)
}

/// Android <string-array> resources are flattened to keys "<name>.0", "<name>.1", ...
enum LocalizedArray {
    static func items(_ name: String) -> [String] {
        let count = StringArrays.counts[name] ?? 0
        return (0..<count).map { L("\(name).\($0)") }
    }

    static func randomItem(_ name: String) -> String {
        items(name).randomElement() ?? ""
    }
}

/// Reads strings from every bundled localization, used to recognise preference values
/// that older Android builds saved in the user's display language instead of English.
enum AllLocalizations {
    private static let bundles: [Bundle] = Bundle.main.localizations.compactMap { code in
        Bundle.main.path(forResource: code, ofType: "lproj").flatMap(Bundle.init(path:))
    }

    static func values(for key: String) -> [String] {
        var result = [L(key)]
        for bundle in bundles {
            let value = bundle.localizedString(forKey: key, value: nil, table: nil)
            if value != key { result.append(value) }
        }
        return result
    }
}
